 S.members.forEach(m=>{if(!Array.isArray(m.czHist))return;const seen=new Set(m.profCz&&m.profCz.rid?[m.profCz.rid]:[]);m.czHist=m.czHist.slice().reverse().filter(h=>!h||!h.rid?!!h:!seen.has(h.rid)&&seen.add(h.rid)).reverse()});
